import json
import re
from datetime import datetime
from collections import defaultdict

# Turkish month names
TURKISH_MONTHS = {
    'ocak': 1, 'şubat': 2, 'mart': 3, 'nisan': 4, 'mayıs': 5, 'haziran': 6,
    'temmuz': 7, 'ağustos': 8, 'eylül': 9, 'ekim': 10, 'kasım': 11, 'aralık': 12
}

def parse_tutar(val):
    """Parse tutar according to rules."""
    if isinstance(val, (int, float)):
        return float(val)
    if not isinstance(val, str):
        return None

    # Remove currency symbols and spaces
    s = val.replace('₺', '').replace('TL', '').replace('tl', '').replace(' ', '').strip()

    # Handle scientific notation
    if 'e' in s.lower():
        try:
            return float(s)
        except:
            return None

    has_dot = '.' in s
    has_comma = ',' in s

    if has_dot and has_comma:
        # Both present: . is thousands, , is decimal
        s = s.replace('.', '')
        s = s.replace(',', '.')
        try:
            return float(s)
        except:
            return None
    elif has_comma:
        # Only comma: decimal separator
        s = s.replace(',', '.')
        try:
            return float(s)
        except:
            return None
    elif has_dot:
        # Only dot: check if exactly 3 digits after
        parts = s.split('.')
        if len(parts) == 2 and len(parts[1]) == 3:
            # Thousands separator
            s = s.replace('.', '')
            try:
                return float(s)
            except:
                return None
        else:
            # Decimal separator
            try:
                return float(s)
            except:
                return None
    else:
        # No separators
        try:
            return float(s)
        except:
            return None

def parse_tarih(val):
    """Parse date according to rules."""
    if not isinstance(val, str):
        return None

    s = val.strip()

    # YYYY-MM-DD
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        try:
            return datetime.strptime(s, '%Y-%m-%d').date()
        except:
            return None

    # YYYY/MM/DD
    if re.match(r'^\d{4}/\d{2}/\d{2}$', s):
        try:
            return datetime.strptime(s, '%Y/%m/%d').date()
        except:
            return None

    # DD.MM.YYYY
    if re.match(r'^\d{2}\.\d{2}\.\d{4}$', s):
        try:
            return datetime.strptime(s, '%d.%m.%Y').date()
        except:
            return None

    # G Ay YYYY (Turkish month name)
    # e.g., "2 Nisan 2025", "15 Mayıs 2025"
    match = re.match(r'^(\d{1,2})\s+([\wğüşıöçĞÜŞİÖÇ]+)\s+(\d{4})$', s, re.IGNORECASE)
    if match:
        day = int(match.group(1))
        month_name = match.group(2).lower()
        year = int(match.group(3))
        month = TURKISH_MONTHS.get(month_name)
        if month:
            try:
                return datetime(year, month, day).date()
            except:
                return None

    return None

def is_valid_record(obj):
    """Check if object has all required fields and they parse correctly."""
    required = ['id', 'musteri', 'tutar', 'tarih', 'durum']
    if not all(k in obj for k in required):
        return False

    # Parse tutar
    tutar = parse_tutar(obj['tutar'])
    if tutar is None:
        return False

    # Parse tarih
    tarih = parse_tarih(obj['tarih'])
    if tarih is None:
        return False

    return True

# Read file
with open('siparisler.jsonl', 'r', encoding='utf-8') as f:
    lines = f.readlines()

valid_records = {}  # id -> record (last valid wins)
hatali_satir = 0

for line_num, line in enumerate(lines, 1):
    line = line.rstrip('\n\r')

    # Skip empty or whitespace-only lines
    if not line.strip():
        continue

    # Try to parse JSON
    try:
        obj = json.loads(line)
    except json.JSONDecodeError:
        hatali_satir += 1
        continue

    # Must be a JSON object (not array, etc.)
    if not isinstance(obj, dict):
        hatali_satir += 1
        continue

    # Validate record
    if is_valid_record(obj):
        # Normalize
        record = {
            'id': obj['id'],
            'musteri': obj['musteri'].strip(),
            'tutar': parse_tutar(obj['tutar']),
            'tarih': parse_tarih(obj['tarih']),
            'durum': obj['durum'].strip().lower()
        }
        valid_records[obj['id']] = record
    else:
        hatali_satir += 1

# Now compute statistics
gecerli_kayit = len(valid_records)

# Iptal sayısı
unique_valid = list(valid_records.values())
iptal_sayisi = sum(1 for r in unique_valid if r['durum'] == 'iptal')

# Toplam tutar (non-iptal)
toplam_tutar = sum(r['tutar'] for r in unique_valid if r['durum'] != 'iptal')

# Aylik tutarlar (non-iptal)
aylik = defaultdict(float)
for r in unique_valid:
    if r['durum'] != 'iptal':
        key = r['tarih'].strftime('%Y-%m')
        aylih[key] += r['tutar']

# En çok harcanan müşteri (non-iptal)
musteri_tutar = defaultdict(float)
for r in unique_valid:
    if r['durum'] != 'iptal':
        musteri_tutar[r['musteri']] += r['tutar']

en_cok_harcayan = max(musteri_tutar.items(), key=lambda x: x[1])[0] if musteri_tutar else ""

# Round to 2 decimals
def round2(x):
    return round(x + 1e-10, 2)

toplam_tutar = round2(toplam_tutar)
aylik = {k: round2(v) for k, v in aylih.items()}

result = {
    "gecerli_kayit": gecerli_kayit,
    "hatali_satir": hatali_satir,
    "iptal_sayisi": iptal_sayisi,
    "toplam_tutar": toplam_tutar,
    "aylik": dict(sorted(aylik.items())),
    "en_cok_harcayan": en_cok_harcayan
}

print(json.dumps(result, ensure_ascii=False, indent=2))

# Write to file
with open('ozet.json', 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

