    if parse_tarih(obj['tarih']) is None:
        return False
    return True

with open('siparisler.jsonl', 'r', encoding='utf-8') as f:
    lines = f.readlines()

valid_records = {}
hatali_satir = 0

for line in lines:
    line = line.rstrip('\n\r')
    if not line.strip():
        continue
    try:
        obj = json.loads(line)
    except json.JSONDecodeError:
        hatali_satir += 1
        continue
    if not isinstance(obj, dict):
        hatali_satir += 1
        continue
    if is_valid_record(obj):
        record = {
            'id': obj['id'],
            'musteri': obj['musteri'].strip(),
            'tutar': parse_tutar(obj['tutar']),
            'tarih': parse_tarih(obj['tarih']),
            'durum': obj['durum'].strip().lower()
        }
        valid_records[obj['id']] = record
    else:
        hatali_satir += 1

gecerli_kayit = len(valid_records)
unique_valid = list(valid_records.values())
iptal_sayisi = sum(1 for r in unique_valid if r['durum'] == 'iptal')
toplam_tutar = sum(r['tutar'] for r in unique_valid if r['durum'] != 'iptal')

aylik = defaultdict(float)
for r in unique_valid:
    if r['durum'] != 'iptal':
        key = r['tarih'].strftime('%Y-%m')
        aylih[key] += r['tutar']

musteri_tutar = defaultdict(float)
for r in unique_valid:
    if r['durum'] != 'iptal':
        musteri_tutar[r['musteri']] += r['tutar']
en_cok_harcayan = max(musteri_tutar.items(), key=lambda x: x[1])[0] if musteri_tutar else ""

def round2(x):
    return round(x + 1e-10, 2)
toplam_tutar = round2(toplam_tutar)
aylik = {k: round2(v) for k, v in aylih.items()}

result = {
    "gecerli_kayit": gecerli_kayit,
    "hatali_satir": hatali_satir,
    "iptal_sayisi": iptal_sayisi,
    "toplam_tutar": toplam_tutar,
    "aylik": dict(sorted(aylik.items())),
    "en_cok_harcayan": en_cok_harcayan
}

print(json.dumps(result, ensure_ascii=False, indent=2))
with open('ozet.json', 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print("\nWritten to ozet.json")
